/** One circle per leaf, sized by value; groups are the legend order and the color domain. */
export type Data = { modules: { id: string; value: number }[]; groups: string[] };

const DEMO: Data = { modules: toolkitModules, groups: MODULE_GROUPS };

type PackDatum = { id: string; value: number; children?: Data['modules'] };

const MARGIN = 1; // keeps the outermost circle's edge off the viewBox
const PADDING = 3;
const FONT_SIZE = 10;
/** Mean advance width of 10px sans-serif, used to drop labels wider than their circle. */
const CHAR_WIDTH = 5.6;
const LEGEND_COLUMNS = 4;
const LEGEND_ROW = 17;
/** The gallery background, composited into each fill so label ink can be chosen from it. */
const BG = '#16181a';

const format = d3.format(',d');
const groupOf = (id: string) => id.split('.')[1];
const nameOf = (id: string) => id.split('.')[2];
/** "LineSimplifier" -> ["Line", "Simplifier"], so long names stack instead of overflowing. */
const wordsOf = (name: string) => name.split(/(?=[A-Z][a-z])|\s+/g).filter(Boolean);

/** Every line must clear the circle at its own height, where the chord is narrower than 2r. */
function labelFits(lines: string[], r: number): boolean {
  return lines.every((line, i) => {
    const baseline = (i - (lines.length - 1) / 2 + 0.35) * FONT_SIZE;
    const reach = Math.max(Math.abs(baseline - 0.72 * FONT_SIZE), Math.abs(baseline + 0.2 * FONT_SIZE));
    return (line.length * CHAR_WIDTH) / 2 <= Math.sqrt(Math.max(0, r * r - reach * reach));
  });
}

export default function BubbleChart({ data = DEMO, width }: { data?: Data; width: number }) {
  const side = Math.max(width - MARGIN * 2, 1);
  const legendHeight = Math.ceil(data.groups.length / LEGEND_COLUMNS) * LEGEND_ROW + 8;
  const height = legendHeight + side + MARGIN * 2;

  const palette = useMemo(() => {
    const scale = d3.scaleOrdinal<string, string>(data.groups, d3.schemeTableau10);
    return new Map(
      data.groups.map((group) => {
        const fill = d3.interpolateRgb(BG, scale(group))(0.82);
        return [group, { fill, ink: d3.lab(fill).l > 60 ? '#141a1f' : '#eef3f8' }];
      })
    );
  }, [data]);

  const marks = useMemo(() => {
    const root = d3
      .pack<PackDatum>()
      .size([side, side])
      .padding(PADDING)(
        d3
          .hierarchy<PackDatum>({ id: 'orbit', value: 0, children: data.modules }, (d) => d.children)
          .sum((d) => d.value)
      );

    return root.leaves().map((node) => {
      const lines = [...wordsOf(nameOf(node.data.id)), format(node.value ?? 0)];
      return {
        id: node.data.id,
        group: groupOf(node.data.id),
        x: node.x,
        y: node.y,
        r: node.r,
        value: node.value ?? 0,
        lines: labelFits(lines, node.r) ? lines : null
      };
    });
  }, [data, side]);

  if (width === 0) return null;

  const legendColumnWidth = side / LEGEND_COLUMNS;

  return (
    <svg
      viewBox={`${-MARGIN} ${-MARGIN} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Bubble chart of source file sizes for the 88 modules of an invented visualization toolkit, packed as circles colored by module group"
      style={{ display: 'block', font: `${FONT_SIZE}px sans-serif` }}
    >
      <g transform="translate(6,0)" fontSize={11} fill="var(--muted)">
        {data.groups.map((group, i) => (
          <g
            key={group}
            transform={`translate(${(i % LEGEND_COLUMNS) * legendColumnWidth},${
              12 + Math.floor(i / LEGEND_COLUMNS) * LEGEND_ROW
            })`}
          >
            <circle r={4.5} fill={palette.get(group)?.fill} />
            <text x={11} dy="0.32em">
              {group}
            </text>
          </g>
        ))}
      </g>
      <g transform={`translate(0,${legendHeight})`} textAnchor="middle">
        {marks.map(({ id, group, x, y, r, value, lines }) => (
          <g key={id} transform={`translate(${x},${y})`}>
            <title>{`${id}\n${format(value)} bytes`}</title>
            <circle r={r} fill={palette.get(group)?.fill} />
            {lines && (
              <text fill={palette.get(group)?.ink}>
                {lines.map((line, i) => (
                  <tspan
                    key={line + i}
                    x={0}
                    y={`${i - (lines.length - 1) / 2 + 0.35}em`}
                    fillOpacity={i === lines.length - 1 ? 0.7 : 1}
                  >
                    {line}
                  </tspan>
                ))}
              </text>
            )}
          </g>
        ))}
      </g>
    </svg>
  );
}
